void CullLights_SingleThread(uint GridIndex, FCellBounds CellBounds, uint ParentGridIndex)
{
	uint NumVisibleLights = 0;
	uint NumVisibleMegaLights = 0;
	uint bHasRectLights = false;
	uint bHasTexturedLights = false;
	uint LinkOffset = 0xFFFFFFFF;
	FArrayView LocalLightArrayView = InitLocalLightArrayView(ParentGridIndex);
	[loop]
	for (uint Index = 0; Index < LocalLightArrayView.Num; ++Index)
	{
		uint LocalLightIndex = GetPrimitiveIndex(LocalLightArrayView, Index);
		bool bIsRectLight;
		bool bIsTexturedLight;
		bool bOverlapsLight = OverlapsLight(LocalLightIndex, CellBounds, bIsRectLight, bIsTexturedLight);
		if (bOverlapsLight)
		{
			bHasRectLights |= bIsRectLight;
			bHasTexturedLights |= bIsTexturedLight;
			uint NextLink;
			 { 	uint NumToAdd = WaveActiveCountBits( true ) * 1U ; NextLink = 0; 	if( WaveIsFirstLane() ) 		InterlockedAdd( RWCulledLightLinkAllocator[0] , NumToAdd, NextLink ); NextLink = WaveReadLaneFirst( NextLink ) + WavePrefixCountBits( true ) * 1U ; };
			if (NextLink < NumAvailableLinks)
			{
				RWCulledLightLinks[NextLink * 2 + 0] = LocalLightIndex;
				RWCulledLightLinks[NextLink * 2 + 1] = LinkOffset;
				LinkOffset = NextLink;
				++NumVisibleLights;
				if (LocalLightIndex >= MegaLightsSupportedStartIndex)
				{
					++NumVisibleMegaLights;
				}
			}
		}
	}
	uint CulledLightDataStart;
	 { 	uint LocalOffset = WavePrefixSum( NumVisibleLights ); 	uint NumToAdd =  WaveReadLaneAt( LocalOffset + NumVisibleLights , WaveGetActiveLaneIndexLast() ); CulledLightDataStart = 0; 	if( WaveIsFirstLane() ) 		InterlockedAdd( RWCulledLightDataAllocator[0] , NumToAdd, CulledLightDataStart ); CulledLightDataStart = WaveReadLaneFirst( CulledLightDataStart ) + LocalOffset; };
	CulledLightDataStart += ViewCulledDataOffset;
	OutputReversedLinkedList(LinkOffset, NumVisibleLights, CulledLightDataStart, 1);
	RWNumCulledLightsGrid[GridIndex * 2 + 0] = PackCulledLightsGridHeader0(NumVisibleLights, NumVisibleMegaLights);
	RWNumCulledLightsGrid[GridIndex * 2 + 1] = PackCulledLightsGridHeader1(CulledLightDataStart, bHasRectLights, bHasTexturedLights);
}
void CullReflectionCaptures_SingleThread(uint GridIndex, FCellBounds CellBounds, uint ParentGridIndex)
{
	uint NumVisibleCaptures = 0;
	uint LinkOffset = 0xFFFFFFFF;
	FArrayView ReflectionCaptureArrayView = InitReflectionCaptureArrayView(ParentGridIndex);
	[loop]
	for (uint Index = 0; Index < ReflectionCaptureArrayView.Num; ++Index)
	{
		uint ReflectionCaptureIndex = GetPrimitiveIndex(ReflectionCaptureArrayView, Index);
		bool bOverlapsReflectionCapture = OverlapsReflectionCapture(ReflectionCaptureIndex, CellBounds);
		if (bOverlapsReflectionCapture)
		{
			uint NextLink;
			 { 	uint NumToAdd = WaveActiveCountBits( true ) * 1U ; NextLink = 0; 	if( WaveIsFirstLane() ) 		InterlockedAdd( RWCulledLightLinkAllocator[0] , NumToAdd, NextLink ); NextLink = WaveReadLaneFirst( NextLink ) + WavePrefixCountBits( true ) * 1U ; };
			if (NextLink < NumAvailableLinks)
			{
				RWCulledLightLinks[NextLink * 2 + 0] = ReflectionCaptureIndex;
				RWCulledLightLinks[NextLink * 2 + 1] = LinkOffset;
				LinkOffset = NextLink;
				++NumVisibleCaptures;
			}
		}
	}
	uint CulledReflectionCaptureDataStart;
	 { 	uint LocalOffset = WavePrefixSum( NumVisibleCaptures ); 	uint NumToAdd =  WaveReadLaneAt( LocalOffset + NumVisibleCaptures , WaveGetActiveLaneIndexLast() ); CulledReflectionCaptureDataStart = 0; 	if( WaveIsFirstLane() ) 		InterlockedAdd( RWCulledLightDataAllocator[0] , NumToAdd, CulledReflectionCaptureDataStart ); CulledReflectionCaptureDataStart = WaveReadLaneFirst( CulledReflectionCaptureDataStart ) + LocalOffset; };
	CulledReflectionCaptureDataStart += ViewCulledDataOffset;
	OutputReversedLinkedList(LinkOffset, NumVisibleCaptures, CulledReflectionCaptureDataStart, false);
	RWNumCulledLightsGrid[(NumGridCells + GridIndex) * 2 + 0] = NumVisibleCaptures;
	RWNumCulledLightsGrid[(NumGridCells + GridIndex) * 2 + 1] = CulledReflectionCaptureDataStart;
}
